 "content": "from collections import deque


def transform(grid):
    """Slide each colored connected object toward the solid monochrome edge."""
    h, w = len(grid), len(grid[0])
    wall = None
    # Find a complete nonzero single-color boundary line.
    for r in range(h):
        if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r]):
            wall = ("row", r, grid[r][0])
            break
    if wall is None:
        for c in range(w):
            color = grid[0][c]
            if color != 0 and all(grid[r][c] == color for r in range(h)):
                wall = ("col", c, color)
                break
    if wall is None:
        return [row[:] for row in grid]

    axis, line, wall_color = wall
    if axis == "row":
        dr, dc = (-1, 0) if line < h // 2 else (1, 0)
        # The solid row defines direction; boundary position disambiguates it.
        if line == 0:
            dr, dc = -1, 0
        elif line == h - 1:
            dr, dc = 1, 0
        else:
            dr, dc = (-1, 0) if line < h / 2 else (1, 0)
    else:
        if line == 0:
            dr, dc = 0, -1
        elif line == w - 1:
            dr, dc = 0, 1
        else:
            dr, dc = (0, -1) if line < w / 2 else (0, 1)

    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color == wall_color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen
                            and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            objects.append((color, cells))

    # The object nearest the wall settles first, then acts as an obstacle.
    if dr < 0:
        objects.sort(key=lambda obj: min(r for r, _ in obj[1]))
    elif dr > 0:
        objects.sort(key=lambda obj: max(r for r, _ in obj[1]), reverse=True)
    elif dc < 0:
        objects.sort(key=lambda obj: min(c for _, c in obj[1]))
    else:
        objects.sort(key=lambda obj: max(c for _, c in obj[1]), reverse=True)

    if axis == "row":
        settled = {(line, c) for c in range(w)}
    else:
        settled = {(r, line) for r in range(h)}
    final_objects = []
    for color, cells in objects:
        shift = 0
        while True:
            candidate = {(r + dr * (shift + 1), c + dc * (shift + 1)) for r, c in cells}
            if any(r < 0 or r >= h or c < 0 or c >= w for r, c in candidate):
                break
            if candidate & settled:
                break
            shift += 1
        moved = {(r + dr * shift, c + dc * shift) for r, c in cells}
        final_objects.append((color, moved))
        settled.update(moved)

    out = [[0] * w for _ in range(h)]
    if axis == "row":
        out[line] = [wall_color] * w
    else:
        for r in range(h):
            out[r][line] = wall_color
    for color, cells in final_objects:
        for r, c in cells:
            out[r][c] = color
    return out


